package com.oanarinaldi.wakemeup;
import android.media.*;import java.io.*;import java.nio.*;
/** Decodes only the first 25 seconds; keeps mono/stereo PCM in memory, never uploads audio. */
final class AudioImporter {
 static void convert(File source,File destination)throws Exception{
  MediaExtractor ex=new MediaExtractor();MediaCodec decoder=null,encoder=null;MediaMuxer mux=null;
  try{ex.setDataSource(source.getAbsolutePath());int track=-1;MediaFormat format=null;for(int i=0;i<ex.getTrackCount();i++){MediaFormat f=ex.getTrackFormat(i);if(f.getString(MediaFormat.KEY_MIME).startsWith("audio/")){track=i;format=f;break;}}if(track<0)throw new IOException("No audio");int sampleRate=format.getInteger(MediaFormat.KEY_SAMPLE_RATE),channels=format.getInteger(MediaFormat.KEY_CHANNEL_COUNT);if(sampleRate>96000||channels>2)throw new IOException("Choose mono or stereo at 96 kHz or below");ex.selectTrack(track);decoder=MediaCodec.createDecoderByType(format.getString(MediaFormat.KEY_MIME));decoder.configure(format,null,null,0);decoder.start();ByteArrayOutputStream pcm=new ByteArrayOutputStream();boolean inputDone=false,done=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long end=System.nanoTime()+30_000_000_000L;
   while(!done&&System.nanoTime()<end){if(!inputDone){int idx=decoder.dequeueInputBuffer(10000);if(idx>=0){ByteBuffer b=decoder.getInputBuffer(idx);int n=ex.getSampleTime()>=25_000_000?-1:ex.readSampleData(b,0);if(n<0){decoder.queueInputBuffer(idx,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputDone=true;}else{decoder.queueInputBuffer(idx,0,n,ex.getSampleTime(),0);ex.advance();}}}
    int idx=decoder.dequeueOutputBuffer(info,10000);if(idx==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat f=decoder.getOutputFormat();sampleRate=f.getInteger(MediaFormat.KEY_SAMPLE_RATE);channels=f.getInteger(MediaFormat.KEY_CHANNEL_COUNT);if(f.containsKey(MediaFormat.KEY_PCM_ENCODING)&&f.getInteger(MediaFormat.KEY_PCM_ENCODING)!=AudioFormat.ENCODING_PCM_16BIT)throw new IOException("Unsupported PCM encoding");}
    if(idx>=0){if(info.size>0&&info.presentationTimeUs<25_000_000){ByteBuffer b=decoder.getOutputBuffer(idx);b.position(info.offset);int max=(int)Math.min(info.size,(25_000_000L-info.presentationTimeUs)*sampleRate*channels*2/1_000_000);byte[] data=new byte[Math.max(0,max)];b.get(data);pcm.write(data);}done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;decoder.releaseOutputBuffer(idx,false);if(pcm.size()>sampleRate*channels*2*25)done=true;}
   }
   byte[] bytes=pcm.toByteArray();if(bytes.length==0)throw new IOException("No decoded audio");MediaFormat aac=MediaFormat.createAudioFormat(MediaFormat.MIMETYPE_AUDIO_AAC,sampleRate,channels);aac.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);aac.setInteger(MediaFormat.KEY_BIT_RATE,160000);encoder=MediaCodec.createEncoderByType(MediaFormat.MIMETYPE_AUDIO_AAC);encoder.configure(aac,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);encoder.start();mux=new MediaMuxer(destination.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int offset=0,outTrack=-1;inputDone=false;done=false;end=System.nanoTime()+30_000_000_000L;
   while(!done&&System.nanoTime()<end){if(!inputDone){int idx=encoder.dequeueInputBuffer(10000);if(idx>=0){ByteBuffer b=encoder.getInputBuffer(idx);b.clear();int n=Math.min(b.remaining(),bytes.length-offset);n-=n%(channels*2);long time=offset*1_000_000L/(sampleRate*channels*2);if(n>0){b.put(bytes,offset,n);offset+=n;encoder.queueInputBuffer(idx,0,n,time,0);}else{encoder.queueInputBuffer(idx,0,0,time,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputDone=true;}}}
    int idx=encoder.dequeueOutputBuffer(info,10000);if(idx==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){outTrack=mux.addTrack(encoder.getOutputFormat());mux.start();}if(idx>=0){if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){ByteBuffer b=encoder.getOutputBuffer(idx);b.position(info.offset);b.limit(info.offset+info.size);mux.writeSampleData(outTrack,b,info);}done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;encoder.releaseOutputBuffer(idx,false);}
   }if(!done)throw new IOException("Audio conversion timed out");mux.stop();
  }finally{ex.release();if(decoder!=null)decoder.release();if(encoder!=null)encoder.release();if(mux!=null)mux.release();}
 }
}
